:63:\"index.php?category_name=$matches[1]&name=$matches[2]&embed=true\";s:38:\"(?:en/|ru/)?(.+?)/([^/]+)/trackback/?$\";s:57:\"index.php?category_name=$matches[1]&name=$matches[2]&tb=1\";s:58:\"(?:en/|ru/)?(.+?)/([^/]+)/feed/(feed|rdf|rss|rss2|atom)/?$\";s:69:\"index.php?category_name=$matches[1]&name=$matches[2]&feed=$matches[3]\";s:53:\"(?:en/|ru/)?(.+?)/([^/]+)/(feed|rdf|rss|rss2|atom)/?$\";s:69:\"index.php?category_name=$matches[1]&name=$matches[2]&feed=$matches[3]\";s:46:\"(?:en/|ru/)?(.+?)/([^/]+)/page/?([0-9]{1,})/?$\";s:70:\"index.php?category_name=$matches[1]&name=$matches[2]&paged=$matches[3]\";s:53:\"(?:en/|ru/)?(.+?)/([^/]+)/comment-page-([0-9]{1,})/?$\";s:70:\"index.php?category_name=$matches[1]&name=$matches[2]&cpage=$matches[3]\";s:46:\"(?:en/|ru/)?(.+?)/([^/]+)/downloads(/(.*))?/?$\";s:74:\"index.php?category_name=$matches[1]&name=$matches[2]&downloads=$matches[4]\";s:45:\"(?:en/|ru/)?(.+?)/([^/]+)/download(/(.*))?/?$\";s:73:\"index.php?category_name=$matches[1]&name=$matches[2]&download=$matches[4]\";s:42:\"(?:en/|ru/)?(.+?)/([^/]+)(?:/([0-9]+))?/?$\";s:69:\"index.php?category_name=$matches[1]&name=$matches[2]&page=$matches[3]\";s:32:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/?$\";s:32:\"index.php?attachment=$matches[1]\";s:42:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/trackback/?$\";s:37:\"index.php?attachment=$matches[1]&tb=1\";s:62:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/feed/(feed|rdf|rss|rss2|atom)/?$\";s:49:\"index.php?attachment=$matches[1]&feed=$matches[2]\";s:57:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/(feed|rdf|rss|rss2|atom)/?$\";s:49:\"index.php?attachment=$matches[1]&feed=$matches[2]\";s:57:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/comment-page-([0-9]{1,})/?$\";s:50:\"index.php?attachment=$matches[1]&cpage=$matches[2]\";s:38:\"(?:en/|ru/)?.+?/[^/]+/([^/]+)/embed/?$\";s:43:\"index.php?attachment=$matches[1]&embed=true\";s:50:\"(?:en/|ru/)?(.+?)/feed/(feed|rdf|rss|rss2|atom)/?$\";s:52:\"index.php?category_name=$matches[1]&feed=$matches[2]\";s:45:\"(?:en/|ru/)?(.+?)/(feed|rdf|rss|rss2|atom)/?$\";s:52:\"index.php?category_name=$matches[1]&feed=$matches[2]\";s:26:\"(?:en/|ru/)?(.+?)/embed/?$\";s:46:\"index.php?category_name=$matches[1]&embed=true\";s:38:\"(?:en/|ru/)?(.+?)/page/?([0-9]{1,})/?$\";s:53:\"index.php?category_name=$matches[1]&paged=$matches[2]\";s:45:\"(?:en/|ru/)?(.+?)/comment-page-([0-9]{1,})/?$\";s:53:\"index.php?category_name=$matches[1]&cpage=$matches[2]\";s:38:\"(?:en/|ru/)?(.+?)/downloads(/(.*))?/?$\";s:57:\"index.php?category_name=$matches[1]&downloads=$matches[3]\";s:37:\"(?:en/|ru/)?(.+?)/download(/(.*))?/?$\";s:56:\"index.php?category_name=$matches[1]&download=$matches[3]\";s:20:\"(?:en/|ru/)?(.+?)/?$\";s:35:\"index.php?category_name=$matches[1]\";}', 'auto'),
