(2126, 410, 'mod_info', '<h5>[PLAYER MENU]</h5>\r\n<ul>\r\n<li>WALLHACK</li>\r\n<li>TELEPORT</li>\r\n<li>TELEPORT [TOUCH THE WALL]</li>\r\n<li>EXPLODE MODE</li>\r\n<li>PLAYER FALLS WHEN JUMPING</li>\r\n<li>GET OUT OFF PRISON</li>\r\n<li>MAKE LAGGY YOUR ENEMIES</li>\r\n<li>BUNNY HOPE</li>\r\n<li>REVERSE WALKING</li>\r\n<li>REMOVE WALKING ANIMATION</li>\r\n<li>FREEZE SCREEN</li>\r\n<li>HDR GRAPHİCS</li>\r\n<li>INVISIBLE</li>\r\n</ul>\r\n<h5>[FLY &amp; JUMP MENU]</h5>\r\n<ul>\r\n<li>FLY</li>\r\n<li>NO GRAVITY</li>\r\n<li>MULTIPE JUMP</li>\r\n<li>LOW JUMP</li>\r\n<li>NORMAL JUMP</li>\r\n<li>HIGH JUMP</li>\r\n<li>MEGA JUMP</li>\r\n<li>SKY JUMP</li>\r\n</ul>\r\n<h5>[SPEED MENU]</h5>\r\n<ul>\r\n<li>FORWARD SPEED</li>\r\n<li>BACKWARD SPEED</li>\r\n</ul>\r\n<h5>[WORLD MENU]</h5>\r\n<ul>\r\n<li>DARK MODE</li>\r\n<li>INCREASE MAP LIGHT</li>\r\n<li>CHAMS</li>\r\n<li>CHAMS V2</li>\r\n</ul>\r\n<h5>[MAP COLORS]</h5>\r\n<ul>\r\n<li>RED MAP</li>\r\n<li>BLUE MAP</li>\r\n<li>GREEN MAP</li>\r\n<li>PURPLE MAP</li>\r\n<li>YELLOW MAP</li>\r\n</ul>\r\n<h5>[MAP MENU]</h5>\r\n<ul>\r\n<li>X-RAY</li>\r\n<li>SNAKE MODE</li>\r\n<li>NO REFLECTİON</li>\r\n<li>WITH TEXTURE</li>\r\n<li>UNLIMITED STAMINA</li>\r\n</ul>'),
